const principal = 300000;
const annualRate = 0.018;
const years = 25;
const paymentsPerYear = 12;
const monthlyRate = annualRate / paymentsPerYear;
const numberOfPayments = years * paymentsPerYear;
const monthlyPayment = principal * monthlyRate * (1 + monthlyRate) ** numberOfPayments / ((1 + monthlyRate) ** numberOfPayments - 1);

(() => `Monthly payment = CHF ${monthlyPayment.toFixed(2)}

Formula: M = P × r × (1+r)^n / ((1+r)^n − 1)

P = ${principal.toLocaleString()} CHF
r = ${annualRate} ÷ ${paymentsPerYear} = ${monthlyRate}
n = ${years} × ${paymentsPerYear} = ${numberOfPayments}

M = ${principal} × ${monthlyRate} × (1+${monthlyRate})^${numberOfPayments} ÷ ((1+${monthlyRate})^${numberOfPayments}−1) = CHF ${monthlyPayment.toFixed(2)}`)()

const calc = (() => {
  const r = annualRate / 100 / 12, n = years * 12;
  const payment = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  return {r, n, payment, total: payment * n, interest: payment * n - principal};
})()

Plot.plot({
  axis: null,
  color: { legend: true },
  marks: [
    Plot.arc([
      { task: "meetings", hours: 30 },
      { task: "coding", hours: 50 },
      { task: "review", hours: 20 }
    ], {
      x: 0,
      y: 0,
      r: 100,
      fill: "task",
      fillOpacity: 0.8,
      stroke: "white",
      strokeWidth: 2,
      start: (d, i, data) => 2 * Math.PI * data.slice(0, i).reduce((sum, x) => sum + x.hours, 0) / 100 - Math.PI / 2,
      end: (d, i, data) => 2 * Math.PI * data.slice(0, i + 1).reduce((sum, x) => sum + x.hours, 0) / 100 - Math.PI / 2
    })
  ]
})

(() => {
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const r = 110, color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  return htl.svg`<svg viewBox="${-r - 10} ${-r - 10} ${2 * r + 20} ${2 * r + 20}" width="320" height="320">
    ${arcs.map(a => htl.svg`<path d="${arc(a)}" fill="${color(a.data.task)}" stroke="white" stroke-width="2"><title>${a.data.task}: ${a.data.value}%</title></path>
      <text transform="translate(${label.centroid(a)})" text-anchor="middle" fill="white" font-size="12" font-family="sans-serif">${a.data.task} ${a.data.value}%</text>`)}
  </svg>`;
})()
